import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/**
 * Sends the screen's as-of date with every request, so the sheet is read as it stood then and nothing is changed. A
 * request that names its own as-of date (a read of how the sheet stood at an earlier day) keeps it.
 */
export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
  const asOf = inject(Session).asOf();
  return next(asOf === null || req.headers.has('X-As-Of') ? req : req.clone({ setHeaders: { 'X-As-Of': asOf } }));
};

/**
 * Sends the screen's preview date with every request, so the sheet's figures are read as if its today were that date;
 * a change is made under the sheet's real today regardless.
 */
export const previewInterceptor: HttpInterceptorFn = (req, next) => {
  const preview = inject(Session).preview();
  return next(preview === null || req.headers.has('X-Preview') ? req : req.clone({ setHeaders: { 'X-Preview': preview } }));
};
@Component
public class AsOfReader {

    private final SheetSnapshotService snapshots;
    private final TransactionTemplate rolledBack;
    private final ConcurrentHashMap<String, ReentrantLock> locks = new ConcurrentHashMap<>();

    public AsOfReader(SheetSnapshotService snapshots, PlatformTransactionManager transactions) {
        this.snapshots = snapshots;
        this.rolledBack = new TransactionTemplate(transactions);
    }

    /** What the read gives with the sheet as it stood at the end of the date; nothing it changes is kept. */
    public <T> T read(String sheetId, LocalDate asOf, Supplier<T> read) {
        ReentrantLock lock = locks.computeIfAbsent(sheetId, k -> new ReentrantLock());
        lock.lock();
        try {
            return rolledBack.execute(status -> {
                status.setRollbackOnly();
                snapshots.restore(sheetId, asOf);
                AsOfContext.set(asOf);
                try {
                    return read.get();
                } finally {
                    AsOfContext.clear();
                }
            });
        } finally {
            lock.unlock();
        }
    }
}
